--
-- Name: pay_rules; Type: TABLE; Schema: workforce; Owner: -
--

CREATE TABLE workforce.pay_rules (
    id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    full_time_day_rate numeric(14,2) NOT NULL,
    part_time_hour_rate numeric(14,2) NOT NULL,
    replacement_hour_rate numeric(14,2) NOT NULL,
    overtime_after_hours numeric(5,2) NOT NULL,
    overtime_multiplier numeric(5,2) NOT NULL,
    created_at_utc timestamp with time zone NOT NULL,
    created_by uuid,
    updated_at_utc timestamp with time zone,
    updated_by uuid,
    CONSTRAINT ck_pay_rules_overtime_range CHECK ((((overtime_after_hours >= (1)::numeric) AND (overtime_after_hours <= (24)::numeric)) AND ((overtime_multiplier >= (1)::numeric) AND (overtime_multiplier <= (5)::numeric)))),
    CONSTRAINT ck_pay_rules_rates_positive CHECK (((full_time_day_rate > (0)::numeric) AND (part_time_hour_rate > (0)::numeric) AND (replacement_hour_rate > (0)::numeric)))
);


--
